<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {WORD_TABS,WORD_TEMPLATES,wordWindow,wordCapabilities} from './word-state.js';
 import {wordStatistics,wordFindMatches,wordSelectionStyle} from './word-model.js';
 import {inspectPreviewImage} from './preview-codec.js';
 import {wordMenus} from './word-menus.js';
 import {createMicrosoftOfficeNativeView} from './microsoft-office-native.js';
 import './microsoft-office.css';
 import './word.css';
 import {createDocumentFonts} from './document-fonts.svelte.js';
 let {state: wordState,profile,window:actualWindow=null,windowId:providedId=null,execute,registerView,sceneTime=0,available=true,active=true,controls={},getShared=name=>controls.getShared?.(name),getFile=id=>controls.getFile?.(id)}=$props();
 const windowId=$derived(providedId??actualWindow?.id),session=$derived(wordWindow(wordState,windowId)),cap=$derived(wordCapabilities(profile));
 const selected=$derived(session?{...session.document.paragraphs.find(p=>p.id===session.selection.paragraphId),style:wordSelectionStyle(session)}:null),stats=$derived(session?wordStatistics(session.document):null),menus=$derived(wordMenus({state: wordState,profile,windowId})),menu=$derived(menus.find(m=>m.id===session?.menu));
 const selectedImage=$derived(session?.document.images.find(i=>i.id===session.selectedImageId)),selectedTable=$derived(session?.document.tables.find(t=>t.id===session.selectedTableId));
 let root=$state(null),message=$state(''),saveName=$state(''),tableRows=$state(3),tableColumns=$state(3),imageData=$state(''),imageMime=$state('image/png'),imageWidth=$state(240),imageHeight=$state(160),referenceKind=$state('footnote'),referenceText=$state('');
 let originalState,originalProfile,originalId,originalSession,originalWindow,facade,retired=false,restoring=false;
 const current=()=>!retired&&root?.isConnected===true&&wordState===originalState&&profile===originalProfile&&windowId===originalId&&session===originalSession&&actualWindow===originalWindow;
 async function command(suffix,payload={},focusEditor=false){if(!current()||!available||!active)return;const result=await execute(`word.${suffix}`,{windowId},payload);if(current()){message=result?.status==='applied'?'':result?.error?.message??'The document operation is unavailable.';if(result?.status==='applied'&&focusEditor){await tick();if(current())restoreRange(true);}}return result;}
 async function menuAction(item){if(!item.enabled||!item.request||!current())return;const result=await execute(item.request.command,item.request.target,item.request.payload);if(current()){message=result?.status==='applied'?'':result?.error?.message??'Menu operation unavailable.';if(result?.status==='applied')await command('menu',{menu:null});}}
 function nativeRange(node){const selection=node.ownerDocument.getSelection();if(!selection?.rangeCount)return null;const range=selection.getRangeAt(0);if(!node.contains(range.startContainer)||!node.contains(range.endContainer))return null;const before=range.cloneRange();before.selectNodeContents(node);before.setEnd(range.startContainer,range.startOffset);return {start:before.toString().length,end:before.toString().length+range.toString().length};}
 function capture(node,id){if(!current()||restoring)return;const range=nativeRange(node);if(range&&id===session.selection.paragraphId&&range.start===session.selection.start&&range.end===session.selection.end)return;if(range)command('select',{paragraphId:id,...range});}
 function restoreRange(focus=false){if(!current()||!available||!active)return;const selection=session.selection,node=[...root.querySelectorAll('[data-office-paragraph-id]')].find(n=>n.dataset.officeParagraphId===selection.paragraphId);if(!node)return;restoring=true;try{if(focus){node.focus();node.scrollIntoView({block:'nearest'});}const walker=node.ownerDocument.createTreeWalker(node,4),texts=[];let text;while((text=walker.nextNode()))texts.push(text);const point=offset=>{for(const t of texts){if(offset<=t.length)return [t,offset];offset-=t.length;}return [node,node.childNodes.length];};const [start,so]=point(selection.start),[end,eo]=point(selection.end),range=node.ownerDocument.createRange();range.setStart(start,so);range.setEnd(end,eo);const native=node.ownerDocument.getSelection();native.removeAllRanges();native.addRange(range);}finally{restoring=false;}}
 function editor(node,p){let signature='';function update(paragraph){const next=JSON.stringify([paragraph.text,paragraph.runs,paragraph.style,paragraph.fontRevision]);if(next===signature)return;signature=next;const ownFocus=node.ownerDocument.activeElement===node;node.replaceChildren();if(paragraph.runs){for(const run of paragraph.runs){const span=node.ownerDocument.createElement('span');span.textContent=run.text;span.style.fontFamily=documentFonts.css(run.font,run.bold,run.italic);span.style.fontSize=`${run.size}pt`;span.style.fontWeight=run.bold?'700':'400';span.style.fontStyle=run.italic?'italic':'normal';span.style.textDecoration=run.underline?'underline':'none';span.style.color=run.color;node.append(span);}}else node.textContent=paragraph.text;if(ownFocus)queueMicrotask(()=>restoreRange());}update(p);return {update};}
 function input(event,p){const node=event.currentTarget,range=nativeRange(node)??{start:node.textContent.length,end:node.textContent.length};command('paragraph.edit',{paragraphId:p.id,text:node.textContent,...range});}
 async function paragraphKey(event,p){const range=nativeRange(event.currentTarget);if(event.key==='Enter'){event.preventDefault();capture(event.currentTarget,p.id);await command('paragraph.split',{},true);}else if(event.key==='Tab'){event.preventDefault();capture(event.currentTarget,p.id);await command('text.insert',{text:'\t'},true);}else if(range&&range.start===range.end&&(event.key==='Backspace'&&range.start===0&&session.document.paragraphs[0].id!==p.id||event.key==='Delete'&&range.end===p.text.length&&session.document.paragraphs.at(-1).id!==p.id)){event.preventDefault();capture(event.currentTarget,p.id);await command('paragraph.merge',{direction:event.key==='Backspace'?'previous':'next'},true);}}
 async function clipboardEvent(event,p,suffix){event.preventDefault();capture(event.currentTarget,p.id);await command(suffix,{},suffix!=='copy');}
 function keyboard(event){if(!current()||!available||!active)return;const modifier=cap.windows?event.ctrlKey:event.metaKey;if(modifier){const key=event.key.toLowerCase(),suffix={s:'save',o:'open',n:'window.new',p:'print',w:'window.close',z:event.shiftKey?'redo':'undo',y:'redo',f:'dialog',x:'cut',c:'copy',v:'paste'}[key];if(suffix){event.preventDefault();command(suffix,key==='f'?{dialog:'find'}:key==='s'&&event.shiftKey?{saveAs:true}:{},['cut','paste'].includes(suffix));}else if(['b','i','u'].includes(key)){event.preventDefault();const field={b:'bold',i:'italic',u:'underline'}[key];format({[field]:!selected.style[field]});}}else if(event.key==='Escape'){command('dialog',{dialog:null});command('menu',{menu:null});}}
 const format=style=>command('format',{style});
 const openDialog=dialog=>command('dialog',{dialog});
 async function saveAndClose(){const result=await command('save');if(result?.status==='applied'&&current())await command('window.close');}
 function configureFind(key,value){command('find.configure',{...session.find,[key]:value});}
 async function insertTable(){const result=await command('table.insert',{rows:Number(tableRows),columns:Number(tableColumns)});if(result?.status==='applied')command('dialog',{dialog:null});}
 async function chooseImage(){const result=await command('image.open');if(result?.status==='applied'&&current())await command('dialog',{dialog:null});}
 async function insertImage(){if(!current())return;const spec={content:imageData,mime:imageMime,width:Number(imageWidth),height:Number(imageHeight)},source=JSON.stringify(wordState),sourceWindow=JSON.stringify(actualWindow),sourceTime=sceneTime,guard=()=>current()&&available&&active&&JSON.stringify(wordState)===source&&JSON.stringify(actualWindow)===sourceWindow&&sceneTime===sourceTime&&imageData===spec.content&&imageMime===spec.mime&&Number(imageWidth)===spec.width&&Number(imageHeight)===spec.height;try{await inspectPreviewImage(spec.content,guard);if(!guard())return;const result=await command('image.insert',spec);if(result?.status==='applied')command('dialog',{dialog:null});}catch(error){if(guard())message=error.message;}}
 async function insertReference(){const result=await command('reference.insert',{kind:referenceKind,text:referenceText},true);if(result?.status==='applied')command('dialog',{dialog:null});}
 onMount(()=>{originalState=wordState;originalProfile=profile;originalId=windowId;originalSession=session;originalWindow=actualWindow;facade=createMicrosoftOfficeNativeView({getRoot:()=>root,getState:()=>wordState,getProfile:()=>profile,windowId,appId:'word',session:wordWindow,execute,available:()=>current()&&available&&active,tick});registerView?.(windowId,facade);return()=>{retired=true;facade.destroy();registerView?.(originalId,null,facade);};});
 $effect(()=>{const selection=session?.selection;if(selection){const rangeKey=`${selection.paragraphId}:${selection.start}:${selection.end}`;if(root&&rangeKey)tick().then(()=>{if(current())restoreRange();});}});
 const documentFonts=createDocumentFonts({getShared:name=>getShared(name),getFile:id=>getFile(id),getRoot:()=>root,getOwner:()=>[wordState,profile,actualWindow,windowId,session]});
</script>

<section bind:this={root} class="office-shell word-app" class:windows={cap.windows} class:classic={cap.classic} class:golden={cap.golden} data-profile={typeof profile==='string'?profile:profile.id} data-word-window-id={windowId} role="region" aria-label="Microsoft Word" tabindex="0" onkeydown={keyboard}>
 {#if session}
 <header class="office-caption word-caption">
 {#if !cap.windows}<WindowControls active={active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} fullScreen={controls.fullScreen} zoomed={controls.zoomed}/>{/if}
 <div class="word-quick-access"><button data-office-control="save" aria-label="Save" onclick={()=>command('save')}>▣</button><button data-office-control="undo" aria-label="Undo" disabled={!session.history.undo.length} onclick={()=>command('undo')}>↶</button><button data-office-control="redo" aria-label="Redo" disabled={!session.history.redo.length} onclick={()=>command('redo')}>↷</button></div>
 <strong>{session.document.title}{session.dirty?' — Edited':''} — Word</strong><input class="word-caption-search" data-office-control="caption-search" aria-label="Search in Document" placeholder="Search in Document" value={session.find.text} maxlength="256" oninput={e=>configureFind('text',e.currentTarget.value)} onkeydown={e=>{if(e.key==='Enter'){e.preventDefault();command('find.next',{},true);}}}/><span>{cap.version}</span>
 </header>
 {#if menu}<div class="word-menu" role="menu">{#each menu.children as item}<button role="menuitem" data-office-control={`menuitem:${item.id}`} disabled={!item.enabled} onclick={()=>menuAction(item)}>{item.checked?'✓ ':''}{item.label}<kbd>{item.shortcut??''}</kbd></button>{/each}</div>{/if}
 <nav class="office-ribbon-tabs" aria-label="Ribbon tabs" inert={!available||!active}>{#if cap.windows}<button data-office-control="menu:file" aria-expanded={session.menu==='file'} onclick={()=>command('menu',{menu:session.menu==='file'?null:'file'})}>File</button>{/if}{#each WORD_TABS.filter(tab=>!['Table Design','Table Layout','Picture Format'].includes(tab)||tab==='Picture Format'&&selectedImage||['Table Design','Table Layout'].includes(tab)&&selectedTable) as tab}<button data-office-control={`tab:${tab}`} class:selected={session.tab===tab} aria-pressed={session.tab===tab} onclick={()=>command('tab',{tab})}>{tab}</button>{/each}<button class="word-share" data-office-control="share" onclick={()=>command('share')}>Share</button></nav>
 <div class="office-ribbon word-ribbon" inert={!available||!active}>
 {#if session.tab==='Home'}
 <div class="office-ribbon-group"><button class="word-large-tool" data-office-control="paste" onclick={()=>command('paste',{},true)}><b>▣</b>Paste</button><div><button data-office-control="cut" disabled={session.selection.start===session.selection.end} onclick={()=>command('cut',{},true)}>Cut</button><button data-office-control="copy" disabled={session.selection.start===session.selection.end} onclick={()=>command('copy')}>Copy</button></div><small>Clipboard</small></div>
 <div class="office-ribbon-group word-font-group"><div><select data-office-control="font-family" aria-label="Font family" value={selected.style.fontFamily} onchange={e=>format({fontFamily:e.currentTarget.value})}>{#each documentFonts.choices(selected.style.fontFamily) as font}<option value={font} disabled={!documentFonts.has(font)}>{font}{!documentFonts.has(font)?' (unavailable)':''}</option>{/each}</select><input data-office-control="font-size" aria-label="Font size" type="number" min="6" max="96" value={selected.style.fontSize} onchange={e=>format({fontSize:Number(e.currentTarget.value)})}/></div><div>{#each [['bold','B'],['italic','I'],['underline','U']] as [field,label]}<button data-office-control={`font:${field}`} aria-label={field} aria-pressed={selected.style[field]} class:pressed={selected.style[field]} onclick={()=>format({[field]:!selected.style[field]})}>{label}</button>{/each}<input data-office-control="font-color" aria-label="Font color" type="color" value={selected.style.color} onchange={e=>format({color:e.currentTarget.value})}/><button data-office-control="font-dialog" onclick={()=>openDialog('format')}>Font…</button></div><small>Font</small></div>
 <div class="office-ribbon-group"><div>{#each ['left','center','right','justify'] as align}<button data-office-control={`align:${align}`} aria-label={`Align ${align}`} class:pressed={selected.style.align===align} onclick={()=>format({align})}>{align==='left'?'≡':align==='center'?'☰':align==='right'?'≡':'▤'}</button>{/each}</div><div><button data-office-control="bullet" onclick={()=>command('list.apply',{kind:'bullet'})}>• List</button><button data-office-control="number" onclick={()=>command('list.apply',{kind:'number'})}>1. List</button><button data-office-control="remove-list" onclick={()=>command('list.apply',{kind:'none'})}>Clear list</button></div><small>Paragraph</small></div>
 <div class="office-ribbon-group word-styles"><div>{#each ['normal','title','heading1','heading2'] as style}<button data-office-control={`style:${style}`} onclick={()=>command('style.apply',{style})}><span class={style}>AaBb</span>{style==='heading1'?'Heading 1':style==='heading2'?'Heading 2':style}</button>{/each}</div><small>Styles</small></div>
 <div class="office-ribbon-group"><button data-office-control="find" onclick={()=>openDialog('find')}>Find / Replace</button><button data-office-control="inspector" onclick={()=>command('inspector',{panel:session.inspector==='format'?'none':'format'})}>Format Pane</button><small>Editing</small></div>
 {:else if session.tab==='Insert'}
 <div class="office-ribbon-group"><button data-office-control="paragraph-add" onclick={()=>command('paragraph.add',{},true)}>New Paragraph</button><button data-office-control="paragraph-break" onclick={()=>command('paragraph.split',{},true)}>Break</button><small>Pages</small></div>
 <div class="office-ribbon-group"><button class="word-large-tool" data-office-control="insert-table" onclick={()=>openDialog('table')}><b>▦</b>Table</button><small>Tables</small></div><div class="office-ribbon-group"><button class="word-large-tool" data-office-control="insert-image" onclick={()=>openDialog('image')}><b>▧</b>Pictures</button><small>Illustrations</small></div><div class="office-ribbon-group"><button data-office-control="insert-symbol" onclick={()=>command('text.insert',{text:'©'},true)}>© Copyright</button><button data-office-control="insert-em-dash" onclick={()=>command('text.insert',{text:'—'},true)}>— Em Dash</button><small>Symbols</small></div>
 {:else if session.tab==='Design'}
 <div class="office-ribbon-group word-themes">{#each ['office','classic','modern'] as theme}<button data-office-control={`theme:${theme}`} onclick={()=>command('theme',{theme})}><span class={theme}>Aa</span>{theme}</button>{/each}<small>Document Formatting</small></div><div class="office-ribbon-group"><button data-office-control="quote-style" onclick={()=>command('style.apply',{style:'quote'})}>Quotation</button><button data-office-control="design-format" onclick={()=>openDialog('format')}>Font &amp; Color…</button><small>Style Options</small></div>
 {:else if session.tab==='Layout'}
 <div class="office-ribbon-group"><button data-office-control="margins" onclick={()=>openDialog('page-setup')}>Margins…</button><button data-office-control="portrait" onclick={()=>command('page',{...session.document.page,width:Math.min(session.document.page.width,session.document.page.height),height:Math.max(session.document.page.width,session.document.page.height)})}>Portrait</button><button data-office-control="landscape" onclick={()=>command('page',{...session.document.page,width:Math.max(session.document.page.width,session.document.page.height),height:Math.min(session.document.page.width,session.document.page.height)})}>Landscape</button><small>Page Setup</small></div><div class="office-ribbon-group"><button data-office-control="letter-page" onclick={()=>command('page',{width:612,height:792,margin:72})}>US Letter</button><button data-office-control="a4-page" onclick={()=>command('page',{width:595,height:842,margin:72})}>A4</button><small>Size</small></div><div class="office-ribbon-group"><button data-office-control="layout-align" onclick={()=>openDialog('format')}>Paragraph Alignment…</button><small>Paragraph</small></div>
 {:else if session.tab==='References'}
 <div class="office-ribbon-group"><button data-office-control="contents" onclick={()=>command('reference.insert',{kind:'contents'},true)}>Insert Contents List</button><small>Heading-derived Editable Text</small></div><div class="office-ribbon-group"><button data-office-control="reference-dialog" onclick={()=>openDialog('reference')}>Note / Citation…</button><small>References</small></div>
 {:else if session.tab==='Review'}
 <div class="office-ribbon-group"><button class="word-large-tool" data-office-control="word-count" onclick={()=>command('review')}><b>ABC</b>Word Count</button><small>Proofing</small></div><div class="office-ribbon-group"><button data-office-control="review-find" onclick={()=>openDialog('find')}>Find and Replace</button><button data-office-control="review-help" onclick={()=>openDialog('help')}>Editing Capabilities</button><small>Document Review</small></div>
 {:else if session.tab==='View'}
 <div class="office-ribbon-group"><button data-office-control="print-layout" class:pressed={session.view==='print'} onclick={()=>command('view',{mode:'print'})}>Print Layout</button><button data-office-control="draft-view" class:pressed={session.view==='draft'} onclick={()=>command('view',{mode:'draft'})}>Draft</button><small>Views</small></div><div class="office-ribbon-group"><label><input data-office-control="ruler" type="checkbox" checked={session.ruler} onchange={e=>command('view',{ruler:e.currentTarget.checked})}/>Ruler</label><button data-office-control="navigation" onclick={()=>command('inspector',{panel:session.inspector==='navigation'?'none':'navigation'})}>Navigation Pane</button><small>Show</small></div><div class="office-ribbon-group"><button data-office-control="zoom-100" onclick={()=>command('view',{zoom:100})}>100%</button><button data-office-control="zoom-75" onclick={()=>command('view',{zoom:75})}>75%</button><small>Zoom</small></div><div class="office-ribbon-group"><button data-office-control="new-window" onclick={()=>command('window.new',{template:'blank'})}>New Window</button><small>Window</small></div>
 {:else if session.tab==='Table Design'&&selectedTable}
 <div class="office-ribbon-group"><button data-office-control="context-table-insert" onclick={()=>openDialog('table')}>Insert Another Table…</button><button data-office-control="context-table-delete" onclick={()=>command('table.delete',{tableId:selectedTable.id})}>Delete Selected Table</button><small>Actual Document Tables</small></div><div class="office-ribbon-group"><button data-office-control="context-table-layout" onclick={()=>command('tab',{tab:'Table Layout'})}>Rows &amp; Columns</button><small>Table Layout</small></div>
 {:else if session.tab==='Table Layout'&&selectedTable}
 <div class="office-ribbon-group"><button data-office-control="context-row-add" onclick={()=>command('table.row',{tableId:selectedTable.id,action:'append'})}>Insert Row Below</button><button data-office-control="context-column-add" onclick={()=>command('table.column',{tableId:selectedTable.id,action:'append'})}>Insert Column Right</button><small>Rows &amp; Columns</small></div><div class="office-ribbon-group"><button data-office-control="context-row-delete" disabled={selectedTable.rows.length===1} onclick={()=>command('table.row',{tableId:selectedTable.id,action:'delete',row:selectedTable.rows.length-1})}>Delete Last Row</button><button data-office-control="context-column-delete" disabled={selectedTable.rows[0].length===1} onclick={()=>command('table.column',{tableId:selectedTable.id,action:'delete',column:selectedTable.rows[0].length-1})}>Delete Last Column</button><small>Delete</small></div>
 {:else if session.tab==='Picture Format'&&selectedImage}
 <div class="office-ribbon-group word-contextual-tools"><label>Width<input data-office-control="context-picture-width" type="number" min="1" max="1600" value={selectedImage.width} onchange={e=>command('image.resize',{imageId:selectedImage.id,width:Number(e.currentTarget.value),height:selectedImage.height})}/></label><label>Height<input data-office-control="context-picture-height" type="number" min="1" max="1600" value={selectedImage.height} onchange={e=>command('image.resize',{imageId:selectedImage.id,width:selectedImage.width,height:Number(e.currentTarget.value)})}/></label><small>Picture Size (pixels)</small></div><div class="office-ribbon-group"><button data-office-control="context-picture-delete" onclick={()=>command('image.delete',{imageId:selectedImage.id})}>Delete Picture</button><button data-office-control="context-picture-insert" onclick={()=>openDialog('image')}>Insert Another Picture…</button><small>Pictures</small></div>
 {/if}
 </div>
 <div class="office-workspace word-workspace" inert={!available||!active}>
 {#if session.inspector==='navigation'}<aside class="word-navigation"><header><strong>Navigation</strong><button data-office-control="navigation-close" aria-label="Close Navigation" onclick={()=>command('inspector',{panel:'none'})}>×</button></header><label>Search paragraphs<input data-office-control="navigation-find" value={session.find.text} maxlength="256" oninput={e=>configureFind('text',e.currentTarget.value)}/></label><button data-office-control="navigation-next" onclick={()=>command('find.next',{},true)}>Find Next</button><h4>Headings</h4>{#each session.document.paragraphs.filter(p=>p.style.fontSize>=15) as p}<button data-office-control={`heading:${p.id}`} onclick={()=>command('select',{paragraphId:p.id,start:0,end:0},true)}>{p.text||'Untitled heading'}</button>{/each}<h4>Results</h4>{#each wordFindMatches(session.document,session.find.text,session.find.caseSensitive).slice(0,200) as match,index}<button data-office-control={`match:${index}`} onclick={()=>command('select',match,true)}>{session.document.paragraphs.find(p=>p.id===match.paragraphId).text.slice(Math.max(0,match.start-20),match.end+30)}</button>{/each}</aside>{/if}
 <main class="word-document-scroll" aria-label="Document workspace"><div class="word-paper-scale" style:zoom={session.zoom/100}>
 {#if session.ruler}<div class="word-ruler" style:width={`${session.document.page.width}pt`} aria-label="Page ruler in points">{#each Array.from({length:Math.floor(session.document.page.width/72)},(_,i)=>i+1) as inch}<span>{inch}</span>{/each}</div>{/if}
 <article class="word-paper" class:draft={session.view==='draft'} style:width={`${session.document.page.width}pt`} style:min-height={`${session.document.page.height}pt`} style:padding={`${session.document.page.margin}pt`} aria-label={session.document.title}>
 {#each session.document.paragraphs as p (p.id)}<div class="word-paragraph" class:selected={session.selection.paragraphId===p.id} data-office-control={`paragraph:${p.id}`} data-office-paragraph-id={p.id} role="textbox" aria-label={`Paragraph ${session.document.paragraphs.indexOf(p)+1}`} aria-multiline="true" tabindex="0" contenteditable={available&&active} spellcheck="false" use:editor={{fontRevision:documentFonts.revision,text:p.text,runs:p.runs?.map(run=>({...run})),style:{...p.style}}} style:font-family={documentFonts.css(p.style.fontFamily,p.style.bold,p.style.italic)} style:font-size={`${p.style.fontSize}pt`} style:font-weight={p.style.bold?'700':'400'} style:font-style={p.style.italic?'italic':'normal'} style:text-decoration={p.style.underline?'underline':'none'} style:color={p.style.color} style:text-align={p.style.align} oninput={e=>input(e,p)} onpointerup={e=>capture(e.currentTarget,p.id)} onkeyup={e=>capture(e.currentTarget,p.id)} onfocus={e=>capture(e.currentTarget,p.id)} onkeydown={e=>paragraphKey(e,p)} onpaste={e=>clipboardEvent(e,p,'paste')} oncopy={e=>clipboardEvent(e,p,'copy')} oncut={e=>clipboardEvent(e,p,'cut')}></div>{/each}
 {#each session.document.tables as table (table.id)}<section class="word-table-wrapper" class:selected={session.selectedTableId===table.id} aria-label="Document table"><button class="word-object-handle" data-office-control={`table:${table.id}`} onclick={()=>command('table.select',{tableId:table.id})}>▦ Select table</button><table><tbody>{#each table.rows as row,r}<tr>{#each row as cell,c}<td><input data-office-control={`cell:${table.id}:${r}:${c}`} aria-label={`Table ${table.id} row ${r+1} column ${c+1}`} maxlength="8192" value={cell} onfocus={()=>command('table.select',{tableId:table.id})} oninput={e=>command('table.edit',{tableId:table.id,row:r,column:c,text:e.currentTarget.value})}/></td>{/each}</tr>{/each}</tbody></table>{#if session.selectedTableId===table.id}<div class="word-table-tools"><button data-office-control="table-add-row" onclick={()=>command('table.row',{tableId:table.id,action:'append'})}>+ Row</button><button data-office-control="table-add-column" onclick={()=>command('table.column',{tableId:table.id,action:'append'})}>+ Column</button><button data-office-control="table-delete-row" disabled={table.rows.length===1} onclick={()=>command('table.row',{tableId:table.id,action:'delete',row:table.rows.length-1})}>− Last row</button><button data-office-control="table-delete-column" disabled={table.rows[0].length===1} onclick={()=>command('table.column',{tableId:table.id,action:'delete',column:table.rows[0].length-1})}>− Last column</button><button data-office-control="table-delete" onclick={()=>command('table.delete',{tableId:table.id})}>Delete Table</button></div>{/if}</section>{/each}
 {#each session.document.images as image (image.id)}<figure class="word-image" class:selected={session.selectedImageId===image.id}><button data-office-control={`image:${image.id}`} aria-label="Select embedded picture" onclick={()=>command('image.select',{imageId:image.id})}><img src={image.content} width={image.width} height={image.height} alt="Embedded document picture"/></button>{#if session.selectedImageId===image.id}<figcaption><label>Width<input data-office-control="image-width" type="number" min="1" max="1600" value={image.width} onchange={e=>command('image.resize',{imageId:image.id,width:Number(e.currentTarget.value),height:image.height})}/></label><label>Height<input data-office-control="image-height" type="number" min="1" max="1600" value={image.height} onchange={e=>command('image.resize',{imageId:image.id,width:image.width,height:Number(e.currentTarget.value)})}/></label><button data-office-control="image-delete" onclick={()=>command('image.delete',{imageId:image.id})}>Delete Picture</button></figcaption>{/if}</figure>{/each}
 </article></div></main>
 {#if session.inspector==='format'}<aside class="word-inspector"><header><strong>Format Paragraph</strong><button data-office-control="format-close" aria-label="Close Format Pane" onclick={()=>command('inspector',{panel:'none'})}>×</button></header><p>Nonempty text selection formats rich runs. A caret formats the whole paragraph.</p><label>Document title<input data-office-control="document-title" value={session.document.title} maxlength="128" onchange={e=>command('document.title',{title:e.currentTarget.value})}/></label><label>Font<input data-office-control="inspector-font" value={selected.style.fontFamily} maxlength="128" onchange={e=>format({fontFamily:e.currentTarget.value})}/></label><label>Size<input data-office-control="inspector-size" type="number" min="6" max="96" value={selected.style.fontSize} onchange={e=>format({fontSize:Number(e.currentTarget.value)})}/></label>{#each ['bold','italic','underline'] as field}<label><input data-office-control={`inspector:${field}`} type="checkbox" checked={selected.style[field]} onchange={e=>format({[field]:e.currentTarget.checked})}/>{field}</label>{/each}<label>Color<input data-office-control="inspector-color" type="color" value={selected.style.color} onchange={e=>format({color:e.currentTarget.value})}/></label><label>Alignment<select data-office-control="inspector-align" value={selected.style.align} onchange={e=>format({align:e.currentTarget.value})}>{#each ['left','center','right','justify'] as align}<option>{align}</option>{/each}</select></label><button data-office-control="inspector-page" onclick={()=>openDialog('page-setup')}>Page Setup…</button><button data-office-control="paragraph-delete" onclick={()=>command('paragraph.delete',{},true)}>Delete Paragraph</button></aside>{/if}
 </div>
 <footer class="office-statusbar word-statusbar"><span>{stats.words} words · {stats.paragraphs} paragraphs</span><output aria-live="polite">{documentFonts.error||message||session.status}</output><button data-office-control="status-print-view" onclick={()=>command('view',{mode:'print'})}>▤</button><label aria-label="Zoom"><input data-office-control="zoom" type="range" min="50" max="200" value={session.zoom} oninput={e=>command('view',{zoom:Number(e.currentTarget.value)})}/>{session.zoom}%</label></footer>
 {#if session.dialog}
 <div class="word-dialog-backdrop"><section class="office-dialog word-dialog" role="dialog" aria-modal="true" aria-label={session.dialog}><header><strong>{({templates:'New Document',find:'Find and Replace',format:'Font and Paragraph','page-setup':'Page Setup',table:'Insert Table',image:'Insert Picture',reference:'Insert Reference',close:'Save changes?',about:'Document Information',help:'Word Local Editing Help',export:'Export PDF','save-as':'Save As',save:'Save',open:'Open Document'})[session.dialog]}</strong><button data-office-control="dialog-close" aria-label="Close dialog" onclick={()=>openDialog(null)}>×</button></header>
 {#if session.dialog==='templates'}<div class="office-templates word-templates">{#each Object.entries(WORD_TEMPLATES) as [template,label]}<button data-office-control={`template:${template}`} onclick={()=>command('window.new',{template})}><span class="word-template-paper"><b>{template==='blank'?'':label}</b><i></i><i></i><i></i><i></i></span>{label}</button>{/each}</div>
 {:else if session.dialog==='find'}<label>Find paragraph text<input data-office-control="find-text" maxlength="256" value={session.find.text} oninput={e=>configureFind('text',e.currentTarget.value)}/></label><label>Replace with<input data-office-control="replace-text" maxlength="4096" value={session.find.replacement} oninput={e=>configureFind('replacement',e.currentTarget.value)}/></label><label><input data-office-control="find-case" type="checkbox" checked={session.find.caseSensitive} onchange={e=>configureFind('caseSensitive',e.currentTarget.checked)}/>Match case</label><div class="word-dialog-actions"><button data-office-control="find-next" onclick={()=>command('find.next',{},true)}>Find Next</button><button data-office-control="replace-one" onclick={()=>command('replace',{all:false},true)}>Replace</button><button data-office-control="replace-all" onclick={()=>command('replace',{all:true})}>Replace All</button></div>
 {:else if session.dialog==='format'}<p>Font changes affect selected rich text, or the entire paragraph when the selection is a caret. Alignment always affects the paragraph.</p><label>Font<select data-office-control="dialog-font" value={selected.style.fontFamily} onchange={e=>format({fontFamily:e.currentTarget.value})}>{#each documentFonts.choices(selected.style.fontFamily) as font}<option value={font} disabled={!documentFonts.has(font)}>{font}{!documentFonts.has(font)?' (unavailable)':''}</option>{/each}</select></label><label>Size<input data-office-control="dialog-size" type="number" min="6" max="96" value={selected.style.fontSize} onchange={e=>format({fontSize:Number(e.currentTarget.value)})}/></label>{#each ['bold','italic','underline'] as field}<label><input data-office-control={`dialog:${field}`} type="checkbox" checked={selected.style[field]} onchange={e=>format({[field]:e.currentTarget.checked})}/>{field}</label>{/each}<label>Color<input data-office-control="dialog-color" type="color" value={selected.style.color} onchange={e=>format({color:e.currentTarget.value})}/></label><label>Align<select data-office-control="dialog-align" value={selected.style.align} onchange={e=>format({align:e.currentTarget.value})}>{#each ['left','center','right','justify'] as align}<option>{align}</option>{/each}</select></label>
 {:else if session.dialog==='page-setup'}<p>Dimensions and uniform margins are in points (72 points = 1 inch).</p>{#each ['width','height','margin'] as key}<label>{key}<input data-office-control={`page:${key}`} type="number" min={key==='margin'?0:300} max={key==='margin'?200:key==='width'?1600:2000} value={session.document.page[key]} onchange={e=>command('page',{...session.document.page,[key]:Number(e.currentTarget.value)})}/></label>{/each}
 {:else if session.dialog==='table'}<label>Rows<input data-office-control="table-rows" type="number" min="1" max="100" bind:value={tableRows}/></label><label>Columns<input data-office-control="table-columns" type="number" min="1" max="20" bind:value={tableColumns}/></label><button data-office-control="table-insert-confirm" onclick={insertTable}>Insert Table</button>
 {:else if session.dialog==='image'}<p>Choose a genuine PNG/JPEG from Files, or insert explicit image data bytes. No remote or placeholder picture is inserted.</p><button data-office-control="image-choose-file" onclick={chooseImage}>Choose Picture from Files…</button><label>Image data URL<textarea data-office-control="image-data" maxlength="524288" bind:value={imageData}></textarea></label><label>Format<select data-office-control="image-mime" bind:value={imageMime}><option value="image/png">PNG</option><option value="image/jpeg">JPEG</option></select></label><label>Width<input data-office-control="image-insert-width" type="number" min="1" max="1600" bind:value={imageWidth}/></label><label>Height<input data-office-control="image-insert-height" type="number" min="1" max="1600" bind:value={imageHeight}/></label><button data-office-control="image-insert-confirm" onclick={insertImage}>Insert Picture</button>
 {:else if session.dialog==='reference'}<p>Insert editable reference text, not automatic fields.</p><label>Type<select data-office-control="reference-kind" bind:value={referenceKind}><option value="footnote">Note</option><option value="citation">Citation</option><option value="contents">Contents from headings</option></select></label><label>Text<textarea data-office-control="reference-text" maxlength="4096" bind:value={referenceText}></textarea></label><button data-office-control="reference-confirm" onclick={insertReference}>Insert</button>
 {:else if ['save','save-as','export'].includes(session.dialog)}<label>File name<input data-office-control="save-name" maxlength="128" placeholder={`${session.document.title}.${session.dialog==='export'?'pdf':'docx'}`} bind:value={saveName}/></label><button data-office-control="save-confirm" onclick={()=>command(session.dialog==='export'?'export':'save',{...(saveName?{name:saveName}:{}),...(session.dialog==='export'?{format:'pdf'}:{saveAs:session.dialog==='save-as'})})}>{session.dialog==='export'?'Export PDF':'Save'}</button>
 {:else if session.dialog==='open'}<p>Choose an actual DOCX document from Files.</p><button data-office-control="open-confirm" onclick={()=>command('open')}>Choose Document…</button>
 {:else if session.dialog==='close'}<p>Save changes to “{session.document.title}” before closing?</p><div class="word-dialog-actions"><button data-office-control="close-save" onclick={saveAndClose}>Save</button><button data-office-control="close-discard" onclick={()=>command('window.close',{discard:true})}>Discard and Close</button><button data-office-control="close-cancel" onclick={()=>openDialog(null)}>Cancel</button></div>
 {:else if session.dialog==='about'}<h3>Microsoft Word · {cap.version}</h3><dl><dt>Words</dt><dd>{stats.words}</dd><dt>Characters</dt><dd>{stats.characters}</dd><dt>Paragraphs</dt><dd>{stats.paragraphs}</dd><dt>Tables</dt><dd>{stats.tables}</dd><dt>Pictures</dt><dd>{stats.images}</dd></dl><p>{cap.disclosure}</p>
 {:else if session.dialog==='help'}<p>Installed font families are the original shared Font Book/Font Library sources, not proprietary Apple or Microsoft fonts. Enablement and source changes update this mounted document. Unavailable authored family names remain literal and use a safe browser rendering fallback; existing export font-embedding scopes are unchanged.</p><p>Type directly in styled paragraphs. Select text to format rich runs; with only a caret, font formatting applies to the whole paragraph. Enter splits a paragraph; pasted plain text creates paragraphs.</p><p>Tables are editable cell-by-cell; selected tables expose row, column and delete controls. Embedded pictures retain genuine PNG/JPEG bytes and can be resized. Find and Replace searches literal paragraph text with optional case matching.</p><p>References are editable text, not automatic bibliography or footnote fields. Page dimensions use points and uniform margins. DOCX stores all paragraphs, then tables, then images; mixed block ordering and unequal margins are unsupported. Cloud collaboration, tracked changes and spell checking are not simulated.</p><p>{cap.disclosure}</p>
 {/if}<p class="word-dialog-message" role="status">{message}</p><footer><button data-office-control="dialog-done" onclick={()=>openDialog(null)}>Done</button></footer>
 </section></div>
 {/if}
 {:else}<p role="alert">The original canonical Word document session is unavailable.</p>{/if}
</section>
